    '</div>',
  ].join('');
  return { from, to: [lead.email], subject, text: lines.join('\n'), html, headers: { 'X-Entity-Ref-ID': leadId } };
}

function teamAlertEmail(lead, q, { from, to, statusUrl, crm, problems }) {
  const urgent = problems.length > 0;
  const subject = oneLine(
    urgent
      ? `[ACTION NEEDED] Lead from ${lead.company}: ${problems.join('; ')}`
      : `[${q.tier.toUpperCase()} ${q.score}] New lead: ${lead.company}`,
    150,
  );
  const crmName = CRM_NAMES[crm.name] || 'CRM';
  const crmLine = crm.saved
    ? `${crmName} record: ${crm.contactUrl || '(saved; open the CRM to see it)'}`
    : `${crmName}: NOT SAVED. The details below are the only copy; add them by hand.`;
  const text = [
    urgent ? `Something failed for this lead: ${problems.join('; ')}. The lead still got the reply email unless listed above.` : 'New lead qualified by the pipeline.',
    '',
    `Score: ${q.score}/100 (${q.tier}), by ${q.scored_by === 'ai' ? 'Gemini' : 'rules fallback'}${q.fallback_reason ? ` (${q.fallback_reason})` : ''}`,
    `Why: ${q.reason}`,
    `Next step: ${NEXT_STEP_TEXT[q.next_step] || q.next_step}`,
    `Red flags: ${q.red_flags.length ? q.red_flags.join(', ') : 'none'}`,
    '',
    `Name: ${lead.name}`,
    `Email: ${lead.email}`,
    `Company: ${lead.company}`,
    `Website: ${lead.website || '-'}`,
    `Service: ${lead.service} | Budget: ${lead.budget} | Timeline: ${lead.timeline}`,
    '',
    'Message:',
    lead.message,
    '',
    crmLine,
    `Pipeline status: ${statusUrl}`,
  ].join('\n');
  return { from, to: [to], subject, text };
}

const v = $('Validate & spam guard').first().json;
const q = JSON.parse($('Check AI answer').first().json.detail);
const contact = $('Record contact').first().json;
const crm = $('Prepare contact').first().json.crm;
const crmName = crm === 'zoho' ? 'Zoho CRM' : 'HubSpot';
const problems = [];
if (contact.state !== 'ok') problems.push(crmName + (crm === 'zoho' ? ' lead' : ' contact') + ' not saved');
const note = $('Log: note').first().json;
if (note.state === 'failed') problems.push(crmName + ' note not saved');
if ($('Record reply').first().json.state !== 'ok') problems.push('reply email not sent');
const contactId = contact.state === 'ok' ? JSON.parse(contact.detail).contact_id : null;
let contactUrl = null;
if (contactId && crm === 'hubspot' && $env.HUBSPOT_PORTAL_ID) contactUrl = 'https://app.hubspot.com/contacts/' + $env.HUBSPOT_PORTAL_ID + '/record/0-1/' + contactId;
if (contactId && crm === 'zoho' && $env.ZOHO_ORG_ID) contactUrl = ($env.ZOHO_CRM_WEB || 'https://crm.zoho.com') + '/crm/org' + $env.ZOHO_ORG_ID + '/tab/Leads/' + contactId;
const statusUrl = v.public_base + '/status?id=' + v.lead_id;
return [{ json: { problems, body: teamAlertEmail(v.lead, q, { from: $env.EMAIL_FROM_ALERTS || $env.EMAIL_FROM_LEADS, to: $env.TEAM_EMAIL, statusUrl, crm: { name: crm, saved: Boolean(contactId), contactUrl }, problems }) } }];

function event(lead_id, step, state, summary, detail) {
  return { json: { lead_id, step, state, summary: String(summary).slice(0, 300), detail: detail === undefined ? '' : JSON.stringify(detail) } };
}
function errorText(e) {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e.slice(0, 200);
  const parts = [e.message, e.description].filter(Boolean).map(String);
  return (parts.join(': ') || JSON.stringify(e)).replace(/\s+/g, ' ').slice(0, 200);
}
const v = $('Validate & spam guard').first().json;
const res = $input.first().json;
const problems = $('Prepare team alert').first().json.problems;
if (res.error || !res.id) return [event(v.lead_id, 'team_alert', 'failed', 'The team alert could not be sent: ' + errorText(res.error || 'no id returned'), { error: errorText(res.error || 'no id') })];
const summary = problems.length
  ? 'Urgent alert sent to the team: ' + problems.join('; ') + '. Nothing is lost: the alert carries the full lead.'
  : 'The team was emailed the lead, its score and the HubSpot link.';
return [event(v.lead_id, 'team_alert', 'ok', summary, { email_id: res.id, urgent: problems.length > 0, problems })];

